import { chromium } from 'playwright';
const BASE='https://www.statesideqm.com', THEME='158561894555';
const routes=[
['Accessories','/collections/accessories-gifts-collectibles'],['Airsoft','/collections/airsoft-milsim'],['Apparel','/collections/apparel'],['Armed Forces Gear','/collections/armed-forces-gear'],['Art','/collections/art'],['Body Armor','/collections/body-armor-ballistic-protection'],['Books','/collections/literature'],['Child Safety','/collections/child-safety-shop'],['DIVE / SCUBA','/collections/dive-scuba'],['Firearm Accessories','/collections/firearm-accessories'],['First Aid','/collections/first-aid-medical-ifak'],['Flags','/collections/flags-patriotic-decor'],['Flashlights','/collections/flashlights-lighting'],['Footwear','/collections/footwear-gloves-eyewear'],['K9','/collections/k9-dog-gear'],['Knives','/collections/knives-axes-cutlery'],['Morale Patches','/collections/morale-patches-tactical-id'],['Outdoor','/collections/outdoor-preparedness-gear'],['Patriotic','/collections/patriotic-american-heritage'],['Safety Rescue','/collections/safety-rescue-climbing'],['Sta-Brite','/collections/sta-brite-insignia'],['Tactical Gear','/collections/tactical-gear'],['Thin Line','/collections/thin-line'],['Uniforms','/collections/uniforms'],['Watches','/collections/watches'],['Lighters','/collections/zippos-lighters-torches'],['Logo Merch','/collections/stateside-quartermaster-logo-merch'],['Army National Guard','/collections/army-national-guard-series'],['Air National Guard','/collections/air-national-guard-series'],['U.S. Army','/collections/products-built-for-the-line-u-s-army'],['U.S. Navy','/collections/products-built-for-the-line-u-s-navy'],['U.S. Air Force','/collections/products-built-for-the-line-u-s-air-force'],['U.S. Marines','/collections/products-built-for-the-line-u-s-marine-corps'],['U.S. Coast Guard','/collections/products-built-for-the-line-u-s-coast-guard'],['U.S. Space Force','/collections/products-built-for-the-line-u-s-space-force'],['ROTC','/collections/rotc-series'],['JROTC','/collections/jrotc-series'],['Military Schools','/collections/military-schools-academies'],['Law Enforcement','/collections/law-enforcement-corrections'],['Fire EMS SAR','/collections/firefighting-ems-search-rescue']];
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
function preview(path,extra={}){const u=new URL(path,BASE);u.searchParams.set('preview_theme_id',THEME);for(const[k,v]of Object.entries(extra))u.searchParams.set(k,v);return u.toString()}
async function settle(p){await p.waitForFunction(()=>document.querySelector('#MainContent')?.dataset.sqRefineV3Ready==='true',null,{timeout:45000});await p.waitForFunction(()=>{const m=document.querySelector('#MainContent');if(!m)return false;const vis=e=>{if(!e)return false;const r=e.getBoundingClientRect(),s=getComputedStyle(e);return r.width>1&&r.height>1&&s.display!=='none'&&s.visibility!=='hidden'&&Number(s.opacity||1)>0};return [...m.querySelectorAll('.sq-refine-v3-sidebar')].some(vis)&&[...m.querySelectorAll('.sq-refine-v3-results .product-grid')].some(g=>vis(g)&&[...g.querySelectorAll(':scope > .product-grid__item')].some(x=>vis(x)&&x.querySelector('a[href*="/products/"]')))},null,{timeout:45000});await sleep(700)}
async function go(p,path,extra={}){let last;for(let i=0;i<5;i++){try{const r=await p.goto(preview(path,extra),{waitUntil:'domcontentloaded',timeout:90000});if(r?.status()===200){await settle(p);return r}last=new Error('HTTP '+(r?.status()||0))}catch(e){last=e}await sleep([2500,4500,7000,11000,16000][i])}throw last}
async function snap(p){return p.evaluate(()=>{const m=document.querySelector('#MainContent');const vis=e=>{if(!e)return false;const r=e.getBoundingClientRect(),s=getComputedStyle(e);return r.width>1&&r.height>1&&s.display!=='none'&&s.visibility!=='hidden'&&Number(s.opacity||1)>0};const sides=[...m.querySelectorAll('.sq-refine-v3-sidebar')].filter(vis);const legacy=[...m.querySelectorAll('.sq-global-refine-sidebar,.sq-collection-sidebar,.facets-block-wrapper,.facets-container,.facets-wrapper,[class*="filter-sidebar"]')].filter(e=>vis(e)&&!e.classList.contains('sq-refine-v3-sidebar'));const gs=[...m.querySelectorAll('.sq-refine-v3-results .product-grid')];const has=g=>vis(g)&&[...g.querySelectorAll(':scope > .product-grid__item')].some(x=>vis(x)&&x.querySelector('a[href*="/products/"]'));const g=gs.find(x=>x.classList.contains('sq-v3-authoritative-grid')&&has(x))||gs.find(has);const cards=g?[...g.querySelectorAll(':scope > .product-grid__item')].filter(x=>vis(x)&&x.querySelector('a[href*="/products/"]')):[];const rs=cards.slice(0,12).map(x=>x.getBoundingClientRect()),row=rs.length?rs.filter(r=>Math.abs(r.y-rs[0].y)<4).length:0;const s=sides[0],t=s?.querySelector('.sq-refine-v3-sidebar__title'),sr=s?.getBoundingClientRect(),tr=t?.getBoundingClientRect();const groups=s?[...s.querySelectorAll(':scope > details.sq-refine-v3-group')].map(d=>({label:(d.querySelector(':scope > summary')?.textContent||'').replace(/\s+/g,' ').trim(),inputs:d.querySelectorAll('input[type=checkbox]').length,targets:[...d.querySelectorAll('input[data-kind=structural][data-target]')].map(i=>i.dataset.target||'')})):[];return{v3:sides.length,legacy:legacy.length,title:(t?.textContent||'').trim(),titleBg:t?getComputedStyle(t).backgroundColor:'',sideBg:s?getComputedStyle(s).backgroundColor:'',gap:sr&&tr?Math.max(0,sr.right-tr.right):999,position:s?getComputedStyle(s).position:'',cards:cards.length,row,width:rs.length?Math.round(rs[0].width):0,groups,pageSizes:[...m.querySelectorAll('.sq-refine-v3-page-size input')].map(i=>i.value)}})}
function errors(d,path){const e=[];if(d.v3!==1)e.push('V3 sidebars='+d.v3);if(d.legacy)e.push('legacy sidebars='+d.legacy);if(d.title.toUpperCase()!=='REFINE PRODUCTS'||d.titleBg!=='rgb(8, 40, 63)'||d.sideBg!=='rgb(8, 40, 63)'||d.gap>1.5)e.push('header edge/color');if(d.position!=='sticky')e.push('sidebar '+d.position);if(d.cards<1)e.push('no visible products');if(d.row!==Math.min(3,d.cards))e.push('desktop row='+d.row);if(d.cards>=3&&d.width<250)e.push('card width='+d.width);if(d.pageSizes.join(',')!=='50,100,250')e.push('page sizes='+d.pageSizes.join(','));for(const g of d.groups){if(!g.inputs)e.push('empty '+g.label);for(const x of g.targets){if(!x.startsWith('/collections/'))e.push('bad structural '+g.label);else if(!new URL(x,BASE).searchParams.get('sq_root'))e.push('missing sq_root '+g.label)}}if(path==='/collections/literature'){const ls=d.groups.map(g=>g.label);for(const rx of [/publisher/i,/war|conflict|era/i,/branch|service/i,/topic|subject/i])if(!ls.some(x=>rx.test(x)))e.push('books taxonomy '+rx);if(ls.some(x=>/author/i.test(x)))e.push('unsafe Author group visible')}if(path==='/collections/firearm-accessories'&&!d.groups.some(g=>/make\s*\/\s*model/i.test(g.label)))e.push('missing Make/Model');return e}
async function openGroupFor(input){await input.evaluate(el=>{const d=el.closest('details');if(d)d.open=true});await sleep(100)}
const browser=await chromium.launch({headless:true});const ctx=await browser.newContext({viewport:{width:1440,height:1000}});const p=await ctx.newPage();const failures=[],pageErrors=[];p.on('pageerror',e=>{if(/sq-refine|sq-v3/i.test(e.stack||e.message||''))pageErrors.push(e.message)});
for(let i=0;i<routes.length;i++){const[n,path]=routes[i];try{await go(p,path);const d=await snap(p),e=errors(d,path);if(e.length)failures.push(n+': '+e.join(' | '));console.log((e.length?'FAIL ':'PASS ')+(i+1)+'/40 '+n+(e.length?' :: '+e.join(' | '):''))}catch(e){failures.push(n+': '+String(e));console.log('FAIL '+n+' :: '+e)}await sleep(400)}
for(const [name,path] of [['State Guard','/collections/state-guard-series'],['Armored Vehicles','/pages/armored-vehicles-purchase-inquiry']]){try{const r=await p.goto(preview(path),{waitUntil:'domcontentloaded',timeout:90000});await sleep(1000);const x=await p.evaluate(()=>({v3:!!document.querySelector('[data-sq-refine-v3]'),side:!!document.querySelector('.sq-refine-v3-sidebar')}));if(r?.status()!==200||x.v3||x.side)failures.push(name+' protection '+JSON.stringify(x));console.log('PROTECTED '+name+' '+JSON.stringify(x))}catch(e){failures.push(name+' '+e)}}
for(const path of ['/collections/accessories-gifts-collectibles','/collections/apparel','/collections/firearm-accessories','/collections/products-built-for-the-line-u-s-navy']){try{await go(p,path);const g=p.locator('.sq-refine-v3-sidebar details.sq-refine-v3-group').filter({has:p.locator('input[type=checkbox]')}).first();const before=await g.getAttribute('open');await g.locator(':scope > summary').click();await sleep(120);const after=await g.getAttribute('open');await g.locator(':scope > summary').click();if(before!==null||after===null)failures.push(path+' disclosure toggle');const card=p.locator('.sq-refine-v3-results .product-grid:visible .product-grid__item:visible').filter({has:p.locator('a[href*="/products/"]')}).first();const href=await card.locator('a[href*="/products/"]').first().getAttribute('href');if(!href)throw new Error('no product href');const img=card.locator('img:visible').first();if(await img.count())await img.click({timeout:15000});else await card.click({position:{x:20,y:20},timeout:15000});await p.waitForURL(/\/products\//,{timeout:20000});await p.goBack({waitUntil:'domcontentloaded',timeout:90000});await settle(p);if((await snap(p)).v3!==1)failures.push(path+' back lost sidebar');console.log('DEEP PASS '+path)}catch(e){failures.push(path+' deep '+String(e))}}
for(const path of ['/collections/accessories-gifts-collectibles','/collections/apparel']){try{await go(p,path);const input=p.locator('.sq-refine-v3-sidebar input[data-kind=native][data-filter-name][data-filter-value]:not(:checked)').first();if(await input.count()){await openGroupFor(input);const name=await input.getAttribute('data-filter-name'),value=await input.getAttribute('data-filter-value');await input.check();await p.waitForLoadState('domcontentloaded',{timeout:30000}).catch(()=>{});await settle(p);if(!new URL(p.url()).searchParams.getAll(name).includes(value))failures.push(path+' native URL');await p.reload({waitUntil:'domcontentloaded',timeout:90000});await settle(p);const checked=await p.locator(`.sq-refine-v3-sidebar input[data-kind=native][data-filter-name="${name}"][data-filter-value="${value}"]`).first().isChecked().catch(()=>false);if(!checked)failures.push(path+' native persistence');console.log('FILTER PASS '+path)}else failures.push(path+' no native filter')}catch(e){failures.push(path+' native '+String(e))}}
for(const path of ['/collections/literature']){try{await go(p,path);const input=p.locator('.sq-refine-v3-sidebar input[data-kind=structural][data-target^="/collections/"]').first();if(await input.count()){await openGroupFor(input);const target=await input.getAttribute('data-target');if(!new URL(target,BASE).searchParams.get('sq_root'))failures.push(path+' structural missing root');await input.check();await p.waitForLoadState('domcontentloaded',{timeout:30000}).catch(()=>{});await settle(p);if(!p.url().includes('/collections/')||!new URL(p.url()).searchParams.get('sq_root'))failures.push(path+' structural escaped root');console.log('STRUCTURAL PASS '+path)}else failures.push(path+' no structural option')}catch(e){failures.push(path+' structural '+String(e))}}
for(const size of ['50','100','250']){try{await go(p,'/collections/accessories-gifts-collectibles');const input=p.locator(`.sq-refine-v3-page-size input[value="${size}"]`);if(!(await input.isChecked())){await input.check();await p.waitForLoadState('domcontentloaded',{timeout:30000}).catch(()=>{});await settle(p)}await sleep(size==='250'?2000:800);const count=await p.locator('.sq-refine-v3-results .product-grid:visible .product-grid__item:visible').count();if(size!=='50'&&new URL(p.url()).searchParams.get('sq_per_page')!==size)failures.push('page size '+size+' URL');if(count!==Number(size))failures.push('page size '+size+' rendered '+count);console.log('PAGE-SIZE '+size+' count='+count)}catch(e){failures.push('page size '+size+' '+String(e))}}
const mc=await browser.newContext({viewport:{width:390,height:844}});const mp=await mc.newPage();for(const path of ['/collections/accessories-gifts-collectibles','/collections/apparel','/collections/literature','/collections/products-built-for-the-line-u-s-navy']){try{await go(mp,path);const d=await mp.evaluate(()=>{const vis=e=>{if(!e)return false;const r=e.getBoundingClientRect(),s=getComputedStyle(e);return r.width>1&&r.height>1&&s.display!=='none'&&s.visibility!=='hidden'};const m=document.querySelector('#MainContent'),s=[...m.querySelectorAll('.sq-refine-v3-sidebar')].filter(vis),gs=[...m.querySelectorAll('.sq-refine-v3-results .product-grid')];const g=gs.find(x=>vis(x)&&[...x.querySelectorAll(':scope > .product-grid__item')].some(vis));const cards=g?[...g.querySelectorAll(':scope > .product-grid__item')].filter(vis).slice(0,8):[],rs=cards.map(x=>x.getBoundingClientRect()),row=rs.length?rs.filter(r=>Math.abs(r.y-rs[0].y)<4).length:0;return{sidebars:s.length,position:s[0]?getComputedStyle(s[0]).position:'',row,cards:cards.length}});if(d.sidebars!==1||d.position==='sticky'||d.row!==Math.min(2,d.cards)||d.cards<2)failures.push('mobile '+path+' '+JSON.stringify(d));console.log('MOBILE '+path+' '+JSON.stringify(d))}catch(e){failures.push('mobile '+path+' '+String(e))}}await mc.close();
for(const e of pageErrors)failures.push('V3 pageerror '+e);console.log('CUSTOMER-V3-SUMMARY '+JSON.stringify({routes:40,failures:failures.length,pageErrors:pageErrors.length}));for(const f of failures)console.log('FAILURE '+f);await ctx.close();await browser.close();if(failures.length)process.exit(1);
